#include <cmath>
#include <iostream>
#include <limits>

int main() {
    const double cheapest = std::numeric_limits<double>::infinity();
    const double highest = -cheapest;

    std::cout << cheapest << ' ' << highest << '\n';
    std::cout << cheapest - 1000 << ' ' << -1.0 / 0.0 << '\n';

    std::cout << std::boolalpha;
    std::cout << std::isinf(cheapest) << ' ' << std::isinf(3.5) << ' '
              << std::isnan(highest - highest) << '\n';
    return 0;
}

