example.code:
#include <iostream>
#include <optional>

int main() {
    std::optional<int> bestScore;
    std::cout << std::boolalpha;
    std::cout << bestScore.has_value() << ' ' << bestScore.value_or(-1) << '\n';

    bestScore = 88;
    std::cout << bestScore.has_value() << ' ' << bestScore.value() << ' '
              << *bestScore << '\n';
    return 0;
}

