practice.solution:
#include <iostream>
#include <optional>
#include <string>

int main() {
    std::optional<std::string> nickname = std::nullopt;
    std::cout << std::boolalpha;
    std::cout << nickname.has_value() << ' ' << nickname.value_or("none") << '\n';

    nickname = "Ace";
    std::cout << nickname.has_value() << ' ' << *nickname << '\n';
    return 0;
}
